<?php require_once __DIR__.'/includes/bootstrap.php'; $pageTitle='Community Profile'; $info=rows($pdo,'SELECT * FROM barangay_info LIMIT 1')[0]??[]; $officials=rows($pdo,'SELECT * FROM officials ORDER BY sort_order ASC, id ASC'); if(!$officials)$officials=rows($pdo,'SELECT r.First_Name,r.Middle_Name,r.Last_Name,r.Suffix,r.Contact_Number,o.Position,o.Term_start,o.Term_end FROM officials o JOIN residents r ON r.Resident_ID=o.Resident_ID ORDER BY o.Term_start DESC'); require __DIR__.'/includes/header.php'; ?><main><a class="back" href="dashboard.php"><i class="fa-solid fa-arrow-left"></i> Explore information / Community Profile</a><section class="hero"><i class="fa-solid fa-landmark"></i><div><h1>Community Profile</h1><p>Meet the barangay, learn its history, and view current officials.</p></div></section><section class="section grid two"><article class="panel"><h2>History</h2><p><?= nl2br(h($info['history_text']??'','The barangay history will be published by the administration.')) ?></p></article><div><article class="panel"><h2>Vision</h2><p><?= nl2br(h($info['vision_text']??'','A safe, informed, and connected San Isidro.')) ?></p></article><article class="panel" style="margin-top:15px"><h2>Mission</h2><p><?= nl2br(h($info['mission_text']??'','People-centered, fair, and timely public service.')) ?></p></article></div></section><section class="section"><h2>Barangay Officials</h2><div class="grid" style="margin-top:18px"><?php if(!$officials):?><div class="panel empty">No officials have been published yet.</div><?php else:foreach($officials as $o):?><article class="panel"><div style="color:var(--teal);font-size:24px"><i class="fa-solid fa-user"></i></div><h3><?= h($o['name']??trim(($o['First_Name']??'').' '.($o['Middle_Name']??'').' '.($o['Last_Name']??'').' '.($o['Suffix']??'')),'Official') ?></h3><span class="meta"><?= h($o['position']??$o['Position']??'Barangay official') ?><br>Term: <?= h($o['term_start']??$o['Term_start']??'') ?> - <?= h($o['term_end']??$o['Term_end']??'') ?><br>Contact: <?= h($o['contact_email']??$o['Contact_Number']??'Office contact on file') ?></span></article><?php endforeach;endif;?></div></section><section class="section"><article class="panel"><h2>Location & map</h2><p><?= nl2br(h($info['address']??'Barangay San Isidro Hall, San Isidro, Philippines')) ?></p><div style="height:150px;background:#d8ebe4;display:grid;place-items:center;color:var(--teal)"><i class="fa-solid fa-map-location-dot" style="font-size:35px"></i><span>Map placeholder</span></div><div class="actions"><button class="button" onclick="window.print()"><i class="fa-solid fa-print"></i> Print</button><form method="post" action="save-item.php"><input type="hidden" name="csrf_token" value="<?= csrf() ?>"><input type="hidden" name="type" value="profile"><input type="hidden" name="return" value="community-profile.php"><button class="button alt" type="submit" data-requires-login data-authenticated="<?= logged_in()?'1':'0' ?>" data-intent="save this profile"><i class="fa-regular fa-bookmark"></i> Save</button></form></div></article></section></main><?php require __DIR__.'/includes/login-gate-modal.php';require __DIR__.'/includes/footer.php';?>
